css:
.dcx *{ box-sizing: border-box; }
.dcx{ margin: 0; background: #F5F7F3; }
.dcx a{ color: #0B6B3F; text-decoration: none; }
.dcx a:hover{ color: #16A85F; }
.dcx :focus-visible{ outline: 2px solid #16A85F; outline-offset: 3px; }
.dcx [data-mega]{ display: none; }
.dcx [data-navitem]:hover [data-mega],.dcx [data-mega]:hover{ display: block; }
.dcx [data-burger]{ display: none; }
@media (max-width: 1180px){.dcx [data-navlinks],.dcx [data-navlogin]{ display: none !important; }
.dcx [data-burger]{ display: inline-flex !important; }
.dcx [data-hero]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-herofeat]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-ovk]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-ovsplit]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-paper]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-paper] svg[data-arrow]{ display: none !important; }
.dcx [data-life]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-life] > div > svg{ display: none !important; }
.dcx [data-aging]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-agingsplit]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-why]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-conn]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-conn] > div > svg{ display: none !important; }
.dcx [data-close]{ grid-template-columns: minmax(0,1fr) !important; }
}
@media (max-width: 720px){.dcx [data-pad]{ padding-left: 18px !important; padding-right: 18px !important; }
.dcx [data-herofeat],.dcx [data-ovk],.dcx [data-life],.dcx [data-why],.dcx [data-conn]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-h1]{ font-size: 34px !important; }
.dcx [data-h2]{ font-size: 23px !important; }
}
